?><!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Công bố TKB – CDS</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css" rel="stylesheet"><style>body{background:#edf3f8;font-family:Segoe UI,system-ui,sans-serif}.wrap{max-width:1250px}.hero{background:linear-gradient(110deg,#123f64,#2781ba);color:#fff}.steps{display:flex;gap:5px;overflow:auto;background:#fff;padding:7px;border-radius:12px}.steps a{white-space:nowrap;text-decoration:none;color:#526579;font-weight:750;padding:8px 12px;border-radius:8px}.steps a.active{background:#175780;color:#fff}.card{border:1px solid #d5e0e8;border-radius:14px}.week-warning{display:none}</style></head><body><header class="hero"><div class="container-fluid wrap py-3"><h3 class="mb-0"><i class="bi bi-check2-circle"></i> Công bố thời khóa biểu</h3><small>Chỉ bước này mới chuyển bản nháp sang TKB chính</small></div></header><main class="container-fluid wrap py-3"><nav class="steps mb-3"><?php foreach(['versions'=>'1. Phương án','data'=>'2. Khối lượng','constraints'=>'3. Ràng buộc','plan'=>'4. Xem & chỉnh','publish'=>'5. Công bố','guide'=>'Hướng dẫn']as$k=>$label):?><a class="<?=$k==='publish'?'active':''?>" href="/tkb_xep.php?tab=<?=$k?>"><?=e($label)?></a><?php endforeach;?></nav><?php show_flash();?><section class="card p-4"><h4>Phương án: <?=e($plan['name']??'Chưa có')?></h4><?php if(!$plan):?><div class="alert alert-warning">Chưa có phương án để công bố.</div><?php else:?><?php if(!$valid):?><div class="alert alert-warning"><h5><i class="bi bi-exclamation-circle"></i> Phương án chưa hoàn tất</h5><div>Đã xếp: <strong><?=count((array)$plan['entries'])?> tiết</strong> · Chưa xếp: <strong><?=count((array)$plan['unplaced'])?> tiết</strong> · Lỗi/xung đột: <strong><?=count((array)$plan['errors'])?></strong>.</div><small>Vẫn có thể công bố phần đã xếp. Các tiết chưa xếp sẽ không xuất hiện trong TKB chính.</small></div><?php else:?><div class="alert alert-success">Phương án hợp lệ: <?=count($plan['entries'])?> tiết đã xếp.</div><?php endif;?><form method="post" action="/tkb_xep.php" id="publishForm" class="row g-3"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="action" value="publish"><input type="hidden" name="return_tab" value="publish"><input type="hidden" name="plan_id" value="<?=e($plan['id'])?>"><input type="hidden" name="overwrite" id="overwrite" value="0"><input type="hidden" name="confirm_incomplete" id="confirmIncomplete" value="0"><div class="col-md-6"><label class="form-label fw-bold">Tên TKB khi công bố</label><input class="form-control" name="name" value="<?=e($plan['name'])?>" required></div><div class="col-md-6"><label class="form-label fw-bold">Tuần cần công bố</label><select class="form-select" name="school_week_key" id="schoolWeek" required><option value="">Chọn tuần học…</option><?php foreach($weeks as$w):$has=false;foreach($published as$p)if((($p['start_date']??'')===$w['start']&&($p['end_date']??'')===$w['end'])||($p['school_week_key']??'')===$w['key']){$has=true;break;}?><option value="<?=e($w['key'])?>" data-existing="<?=$has?'1':'0'?>"><?=e($w['label'])?> (<?=date('d/m/Y',strtotime($w['start']))?>–<?=date('d/m/Y',strtotime($w['end']))?>)<?=$has?' · Đã có TKB':''?></option><?php endforeach;?></select></div><div class="col-12"><div class="alert alert-warning week-warning" id="weekWarning"><strong>Tuần này đã có thời khóa biểu.</strong> Nếu tiếp tục, bản mới sẽ thay thế bản đang áp dụng; bản cũ vẫn được giữ trong lịch sử.</div><label class="form-check border rounded p-3 bg-light"><input class="form-check-input" type="checkbox" name="confirm_publish" value="1" required> <span class="form-check-label">Tôi đã kiểm tra đúng phương án và đúng tuần cần công bố.</span></label></div><div class="col-12"><button class="btn btn-success btn-lg"><i class="bi bi-cloud-check"></i> Xác nhận công bố</button></div></form><?php endif;?></section></main><script>var select=document.getElementById('schoolWeek'),warning=document.getElementById('weekWarning'),form=document.getElementById('publishForm'),overwrite=document.getElementById('overwrite'),confirmIncomplete=document.getElementById('confirmIncomplete'),incomplete=<?=!$valid?'true':'false'?>,unplacedCount=<?=count((array)($plan['unplaced']??[]))?>,errorCount=<?=count((array)($plan['errors']??[]))?>,planName=<?=json_encode((string)($plan['name']??''),JSON_UNESCAPED_UNICODE)?>;if(select)select.onchange=function(){var exists=this.selectedOptions[0]?.dataset.existing==='1';warning.style.display=exists?'block':'none';overwrite.value=exists?'1':'0'};if(form)form.onsubmit=function(){var option=select.selectedOptions[0],exists=option?.dataset.existing==='1',message='Công bố phương án "<?=e(addslashes($plan['name']??''))?>" sang '+option.textContent.trim()+'?';if(incomplete){var partial='Phương án chưa hoàn tất: còn '+unplacedCount+' tiết chưa sắp và '+errorCount+' lỗi/xung đột.\n\nVẫn công bố phần đã xếp?';if(!confirm(partial)){confirmIncomplete.value='0';return false}confirmIncomplete.value='1'}if(!confirm(message))return false;if(exists&&!confirm('Tuần đã có TKB. Thầy/cô chắc chắn muốn ghi đè bản đang áp dụng? Bản cũ sẽ được giữ trong lịch sử.'))return false;return true};</script></body></html>
